import base64
import pathlib
import subprocess
import sys
import tempfile

subprocess.run(
    [
        sys.executable,
        "-m",
        "pip",
        "install",
        "-q",
        "qiskit",
        "qiskit-machine-learning",
        "numpy",
    ],
    check=True,
)

SOURCES_B64 = {
  "3-4.py": "",
  "3-3.py": "",
  "3-2.py": "",
  "3-1.py": "",
  "torch_connector.py": "",
  "create_qnn.py": "",
  "3-6.py": "",
  "3-5.py": "",
  "2-1.py": ""
}
EXECUTION_ORDER = ["create_qnn.py","torch_connector.py","3-1.py","2-1.py","3-2.py","3-3.py","3-4.py","3-5.py","3-6.py"]

with tempfile.TemporaryDirectory(prefix="quantum-ml-day34-") as tmp:
    root = pathlib.Path(tmp)
    for name, payload in SOURCES_B64.items():
        (root / name).write_bytes(base64.b64decode(payload))

    for name in EXECUTION_ORDER:
        label = f"Day34/{name}"
        print(f"COLAB_SOURCE_START {label}", flush=True)
        subprocess.run([sys.executable, name], cwd=root, check=True)
        print(f"COLAB_SOURCE_OK {label}", flush=True)

print("COLAB_DAY34_SOURCE_EXECUTION_OK", flush=True)
